// vendor/40kdc/src/data/battle-sizes.ts
function pointsLimitForBattleSize(battleSize) {
  switch (battleSize) {
    case "strike-force":
      return 2e3;
    case "incursion":
      return 1e3;
    default:
      return null;
  }
}
function detachmentCapForBattleSize(battleSize) {
  switch (battleSize) {
    case "strike-force":
      return 3;
    case "incursion":
      return 2;
    default:
      return null;
  }
}
function unitLimitForBattleSize(battleSize) {
  switch (battleSize) {
    case "strike-force":
      return 3;
    case "incursion":
      return 2;
    default:
      return null;
  }
}
function enhancementLimitForBattleSize(battleSize) {
  switch (battleSize) {
    case "strike-force":
      return 4;
    case "incursion":
      return 2;
    default:
      return null;
  }
}

